create table public.roles(id uuid primary key default gen_random_uuid(),code text unique not null,name_ar text not null,description text);
create table public.permissions(id uuid primary key default gen_random_uuid(),code text unique not null,name_ar text not null,module text not null);
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text unique,full_name text not null default 'مستخدم',phone text,is_enabled boolean not null default true,is_manager boolean not null default false,created_at timestamptz not null default now(),last_login_at timestamptz);
create table public.user_roles(user_id uuid primary key references public.profiles(id) on delete cascade,role_id uuid not null references public.roles(id),created_at timestamptz not null default now());
create table public.role_permissions(role_id uuid references public.roles(id) on delete cascade,permission_id uuid references public.permissions(id) on delete cascade,primary key(role_id,permission_id));
create table public.settings(key text primary key,value jsonb not null default '{}'::jsonb,updated_by uuid references public.profiles(id),updated_at timestamptz not null default now());
create table public.product_categories(id uuid primary key default gen_random_uuid(),name text unique not null,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.units(id uuid primary key default gen_random_uuid(),name text unique not null,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),product_number text unique not null default ('PROD-'||lpad(nextval('public.product_seq')::text,4,'0')),name text not null,category_id uuid references public.product_categories(id),category_name text,unit_id uuid references public.units(id),unit_name text,cost_price numeric(14,2) not null default 0,sale_price numeric(14,2) not null default 0,minimum_stock numeric(14,3) not null default 0,custom_fields jsonb not null default '{}'::jsonb,notes text,is_active boolean not null default true,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.departments(id uuid primary key default gen_random_uuid(),name text unique not null,created_at timestamptz not null default now());
create table public.job_titles(id uuid primary key default gen_random_uuid(),name text unique not null,created_at timestamptz not null default now());
create table public.shifts(id uuid primary key default gen_random_uuid(),name text unique not null,start_time time,end_time time,grace_minutes integer not null default 0,is_overnight boolean not null default false,created_at timestamptz not null default now());
create table public.employees(id uuid primary key default gen_random_uuid(),employee_number text unique not null default ('EMP-'||lpad(nextval('public.employee_seq')::text,4,'0')),full_name text not null,phone text,address text,department_id uuid references public.departments(id),job_title_id uuid references public.job_titles(id),shift_id uuid references public.shifts(id),employment_date date,wage_type text not null default 'monthly' check(wage_type in('monthly','daily','hourly','piecework')),base_salary numeric(14,2) not null default 0,status text not null default 'active' check(status in('active','suspended','leave','archived')),notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.attendance_records(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),work_date date not null default current_date,check_in_at timestamptz,check_out_at timestamptz,status text not null default 'present',working_minutes integer generated always as(case when check_in_at is not null and check_out_at is not null then greatest(0,extract(epoch from(check_out_at-check_in_at))/60)::integer else null end) stored,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),unique(employee_id,work_date));
create table public.attendance_corrections(id uuid primary key default gen_random_uuid(),attendance_id uuid not null references public.attendance_records(id),old_check_in_at timestamptz,old_check_out_at timestamptz,new_check_in_at timestamptz,new_check_out_at timestamptz,reason text not null,corrected_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.employee_advances(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),amount numeric(14,2) not null check(amount>0),reason text,repayment_amount numeric(14,2) not null default 0,remaining_amount numeric(14,2) not null,advance_date timestamptz not null default now(),payment_method text not null default 'cash',cash_register_id uuid,bank_id uuid,created_by uuid references public.profiles(id),status text not null default 'approved');
create table public.employee_incentives(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),amount numeric(14,2) not null check(amount>0),reason text not null,period_start date,period_end date,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),status text not null default 'approved');
create table public.payroll_periods(id uuid primary key default gen_random_uuid(),period_name text not null,from_date date not null,to_date date not null,status text not null default 'draft',created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz,created_at timestamptz not null default now());
create table public.payroll_records(id uuid primary key default gen_random_uuid(),period_id uuid not null references public.payroll_periods(id) on delete cascade,employee_id uuid not null references public.employees(id),base_amount numeric(14,2) not null default 0,incentives numeric(14,2) not null default 0,deductions numeric(14,2) not null default 0,advance_deduction numeric(14,2) not null default 0,net_amount numeric(14,2) generated always as(base_amount+incentives-deductions-advance_deduction) stored,payment_status text not null default 'unpaid',paid_amount numeric(14,2) not null default 0,paid_at timestamptz,unique(period_id,employee_id));
create table public.customers(id uuid primary key default gen_random_uuid(),name text not null,phone text,notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.warehouses(id uuid primary key default gen_random_uuid(),warehouse_number text unique not null default ('WH-'||lpad(nextval('public.warehouse_seq')::text,3,'0')),name text not null,warehouse_type text not null default 'finished',is_active boolean not null default true,created_at timestamptz not null default now());
create table public.stock_movements(id uuid primary key default gen_random_uuid(),movement_number text unique not null default ('MOV-'||lpad(nextval('public.movement_seq')::text,6,'0')),direction text not null check(direction in('in','out','transfer')),source_type text not null,source_id uuid,from_warehouse_id uuid references public.warehouses(id),to_warehouse_id uuid references public.warehouses(id),movement_date timestamptz not null default now(),status text not null default 'draft',notes text,created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz,created_at timestamptz not null default now());
create table public.stock_movement_lines(id uuid primary key default gen_random_uuid(),movement_id uuid not null references public.stock_movements(id) on delete cascade,product_id uuid not null references public.products(id),quantity numeric(14,3) not null check(quantity>0),unit_name text,cost_price numeric(14,2) not null default 0,notes text);
create table public.suppliers(id uuid primary key default gen_random_uuid(),supplier_number text unique not null default ('SUP-'||lpad(nextval('public.supplier_seq')::text,4,'0')),name text not null,company_name text,phone text,phone2 text,address text,city text,materials text,tax_number text,notes text,is_active boolean not null default true,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.raw_materials(id uuid primary key default gen_random_uuid(),raw_number text unique not null default ('RM-'||lpad(nextval('public.raw_seq')::text,4,'0')),name text not null,code text,unit_name text,is_active boolean not null default true,notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.purchases(id uuid primary key default gen_random_uuid(),purchase_number text unique not null default ('PUR-'||lpad(nextval('public.purchase_seq')::text,6,'0')),supplier_id uuid not null references public.suppliers(id),supplier_invoice text,purchase_at timestamptz not null default now(),discount numeric(14,2) not null default 0,total numeric(14,2) not null default 0,paid_amount numeric(14,2) not null default 0,remaining_amount numeric(14,2) generated always as(greatest(total-paid_amount,0)) stored,payment_method text not null default 'credit',status text not null default 'draft',notes text,created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz);
create table public.purchase_items(id uuid primary key default gen_random_uuid(),purchase_id uuid not null references public.purchases(id) on delete cascade,raw_material_id uuid references public.raw_materials(id),product_id uuid references public.products(id),item_name text not null,quantity numeric(14,3) not null,unit_name text not null,unit_price numeric(14,2) not null,total numeric(14,2) generated always as(quantity*unit_price) stored);
create table public.supplier_payments(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id),purchase_id uuid references public.purchases(id),amount numeric(14,2) not null check(amount>0),payment_method text not null,paid_at timestamptz not null default now(),cash_register_id uuid,bank_id uuid,reference text,created_by uuid references public.profiles(id));
create table public.sales(id uuid primary key default gen_random_uuid(),invoice_number text unique not null default ('INV-'||lpad(nextval('public.invoice_seq')::text,6,'0')),invoice_type text not null default 'sale' check(invoice_type in('sale','proforma','open')),customer_id uuid references public.customers(id),customer_name text not null default 'عميل عادي',warehouse_id uuid references public.warehouses(id),subtotal numeric(14,2) not null default 0,discount_type text not null default 'amount',discount_value numeric(14,2) not null default 0,discount_amount numeric(14,2) not null default 0,crafting_fee numeric(14,2) not null default 0,vat_enabled boolean not null default false,vat_rate numeric(6,3) not null default 0,vat_amount numeric(14,2) not null default 0,total numeric(14,2) not null default 0,paid_amount numeric(14,2) not null default 0,remaining_amount numeric(14,2) generated always as(greatest(total-paid_amount,0)) stored,payment_method text not null default 'cash',status text not null default 'draft',sold_at timestamptz not null default now(),notes text,created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz);
create table public.sale_items(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete cascade,product_id uuid not null references public.products(id),product_name text not null,quantity numeric(14,3) not null check(quantity>0),unit_price numeric(14,2) not null,cost_price numeric(14,2) not null default 0,discount_amount numeric(14,2) not null default 0,line_total numeric(14,2) not null);
create table public.sale_payments(id uuid primary key default gen_random_uuid(),sale_id uuid not null references public.sales(id) on delete cascade,amount numeric(14,2) not null check(amount>0),payment_method text not null,paid_at timestamptz not null default now(),cash_register_id uuid,bank_id uuid,reference text,created_by uuid references public.profiles(id));
create table public.returns(id uuid primary key default gen_random_uuid(),return_number text unique not null default ('RET-'||lpad(nextval('public.return_seq')::text,6,'0')),sale_id uuid not null references public.sales(id),customer_id uuid references public.customers(id),return_at timestamptz not null default now(),subtotal numeric(14,2) not null default 0,vat_amount numeric(14,2) not null default 0,total numeric(14,2) not null default 0,status text not null default 'draft',reason text,notes text,created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz);
create table public.return_items(id uuid primary key default gen_random_uuid(),return_id uuid not null references public.returns(id) on delete cascade,sale_item_id uuid not null references public.sale_items(id),product_id uuid not null references public.products(id),quantity numeric(14,3) not null,good_quantity numeric(14,3) not null default 0,damaged_quantity numeric(14,3) not null default 0,inspection_quantity numeric(14,3) not null default 0,unit_price numeric(14,2) not null,line_total numeric(14,2) not null);
create table public.damaged_goods(id uuid primary key default gen_random_uuid(),damage_number text unique not null default ('DMG-'||lpad(nextval('public.damage_seq')::text,6,'0')),product_id uuid not null references public.products(id),quantity numeric(14,3) not null,unit_name text,source_type text not null,source_id uuid,reason text,status text not null default 'pending',action_quantity numeric(14,3) not null default 0,notes text,created_by uuid references public.profiles(id),created_at timestamptz not null default now(),decided_by uuid references public.profiles(id),decided_at timestamptz);
create table public.cash_registers(id uuid primary key default gen_random_uuid(),cash_number text unique not null default ('CASH-'||lpad(nextval('public.cash_seq')::text,3,'0')),name text not null,type text not null default 'cash',opening_balance numeric(14,2) not null default 0,is_active boolean not null default true,limit_amount numeric(14,2),responsible_id uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.banks(id uuid primary key default gen_random_uuid(),bank_number text unique not null default ('BANK-'||lpad(nextval('public.bank_seq')::text,3,'0')),name text not null,account_name text,masked_account text,opening_balance numeric(14,2) not null default 0,is_active boolean not null default true,responsible_id uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.cash_transactions(id uuid primary key default gen_random_uuid(),transaction_number text unique not null default ('CTX-'||lpad(nextval('public.cash_tx_seq')::text,6,'0')),cash_register_id uuid not null references public.cash_registers(id),direction text not null check(direction in('in','out')),transaction_type text not null,amount numeric(14,2) not null check(amount>0),reference text,related_type text,related_id uuid,transaction_at timestamptz not null default now(),notes text,created_by uuid references public.profiles(id));
create table public.bank_transactions(id uuid primary key default gen_random_uuid(),transaction_number text unique not null default ('BTX-'||lpad(nextval('public.bank_tx_seq')::text,6,'0')),bank_id uuid not null references public.banks(id),direction text not null check(direction in('in','out')),transaction_type text not null,amount numeric(14,2) not null check(amount>0),reference text,related_type text,related_id uuid,transaction_at timestamptz not null default now(),notes text,created_by uuid references public.profiles(id));
create table public.expenses(id uuid primary key default gen_random_uuid(),expense_number text unique not null default ('EXP-'||lpad(nextval('public.expense_seq')::text,6,'0')),category text not null,amount numeric(14,2) not null check(amount>0),payment_method text not null default 'cash',cash_register_id uuid,bank_id uuid,payee text,department text,expense_at timestamptz not null default now(),receipt_url text,status text not null default 'draft',description text,created_by uuid references public.profiles(id),approved_by uuid references public.profiles(id),approved_at timestamptz);
create table public.activity_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,old_data jsonb,new_data jsonb,reason text,severity text not null default 'normal',created_at timestamptz not null default now());
-- Helper functions and baseline seeds.
create or replace function public.current_user_is_manager() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and is_manager=true and is_enabled=true)$$;
create or replace function public.current_user_has_permission(p_code text) returns boolean language sql stable security definer set search_path=public as $$select public.current_user_is_manager() or exists(select 1 from public.user_roles ur join public.role_permissions rp on rp.role_id=ur.role_id join public.permissions p on p.id=rp.permission_id where ur.user_id=auth.uid() and p.code=p_code)$$;
insert into public.roles(code,name_ar,description) values('manager','مدير','صلاحية كاملة'),('finance','حسابات','الخزائن والمرتبات والتقارير المالية'),('sales','مبيعات','العملاء والفواتير والمرتجعات'),('inventory','مخزن وموردين','المشتريات والمخزون والمواد الخام'),('production','إنتاج','أوامر الإنتاج والتالف') on conflict(code) do update set name_ar=excluded.name_ar;
insert into public.permissions(code,name_ar,module) values
('dashboard.view','لوحة التحكم','dashboard'),('products.view','عرض المنتجات','products'),('products.create','إضافة منتج','products'),('products.edit','تعديل منتج','products'),('sales.view','عرض المبيعات','sales'),('sales.create','إضافة فاتورة','sales'),('sales.approve','اعتماد فاتورة','sales'),('sales.print','طباعة فاتورة','sales'),('returns.view','عرض المرتجعات','returns'),('returns.create','إضافة مرتجع','returns'),('inventory.view','عرض المخزون','inventory'),('inventory.create','حركة مخزن','inventory'),('purchases.view','عرض المشتريات','purchases'),('purchases.create','إضافة شراء','purchases'),('production.view','عرض الإنتاج','production'),('production.create','أمر إنتاج','production'),('employees.view','عرض الموظفين','employees'),('employees.create','إضافة موظف','employees'),('attendance.view','عرض الحضور','attendance'),('attendance.create','تسجيل الحضور','attendance'),('attendance.correct','تصحيح الحضور','attendance'),('payroll.view','عرض المرتبات','payroll'),('payroll.manage','إدارة المرتبات','payroll'),('cash.manage','إدارة الخزائن','finance'),('bank.manage','إدارة البنوك','finance'),('expenses.view','عرض المصروفات','expenses'),('expenses.create','إضافة مصروف','expenses'),('reports.view','عرض التقارير','reports'),('audit.view','عرض التدقيق','audit') on conflict(code) do nothing;
insert into public.profiles(id,email,full_name,is_manager) select id,email,'عصام الجبل',true from auth.users where lower(email)=lower('alsndlmsn@gmail.com') on conflict(id) do update set full_name='عصام الجبل',is_manager=true,is_enabled=true;
insert into public.user_roles(user_id,role_id) select p.id,r.id from public.profiles p cross join public.roles r where p.is_manager=true and r.code='manager' on conflict(user_id) do update set role_id=excluded.role_id;
insert into public.role_permissions(role_id,permission_id) select r.id,p.id from public.roles r cross join public.permissions p where r.code in('finance','sales','inventory','production') and ((r.code='finance' and p.module in('dashboard','finance','expenses','payroll','employees','attendance','reports')) or (r.code='sales' and p.module in('dashboard','sales','returns','products')) or (r.code='inventory' and p.module in('dashboard','inventory','products','purchases')) or (r.code='production' and p.module in('dashboard','production','inventory','products'))) on conflict do nothing;
-- RLS: all data is protected behind authenticated sessions; later policies can narrow by role.
do $$ declare t text; begin foreach t in array array['roles','permissions','profiles','user_roles','role_permissions','settings','product_categories','units','products','departments','job_titles','shifts','employees','attendance_records','attendance_corrections','employee_advances','employee_incentives','payroll_periods','payroll_records','customers','warehouses','stock_movements','stock_movement_lines','suppliers','raw_materials','purchases','purchase_items','supplier_payments','sales','sale_items','sale_payments','returns','return_items','damaged_goods','cash_registers','banks','cash_transactions','bank_transactions','expenses','activity_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy %I on public.%I for all to authenticated using(true) with check(true)',t||'_access',t); end loop; end $$;
create or replace function public.write_activity_log() returns trigger language plpgsql security definer set search_path=public as $$begin if tg_op='INSERT' then insert into activity_logs(actor_id,action,entity_type,entity_id,new_data) values(auth.uid(),tg_op,tg_table_name,(to_jsonb(new)->>'id')::uuid,to_jsonb(new)); return new; elsif tg_op='UPDATE' then insert into activity_logs(actor_id,action,entity_type,entity_id,old_data,new_data) values(auth.uid(),tg_op,tg_table_name,(to_jsonb(new)->>'id')::uuid,to_jsonb(old),to_jsonb(new)); return new; else insert into activity_logs(actor_id,action,entity_type,entity_id,old_data) values(auth.uid(),tg_op,tg_table_name,(to_jsonb(old)->>'id')::uuid,to_jsonb(old)); return old; end if; end; $$;
create trigger audit_products after insert or update or delete on public.products for each row execute function public.write_activity_log();
create trigger audit_sales after insert or update or delete on public.sales for each row execute function public.write_activity_log();
create trigger audit_stock after insert or update or delete on public.stock_movements for each row execute function public.write_activity_log();
create trigger audit_expenses after insert or update or delete on public.expenses for each row execute function public.write_activity_log();
create trigger audit_employees after insert or update or delete on public.employees for each row execute function public.write_activity_log();
